import{_ as r,o as l,c as o,a2 as s}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"财务管理 - 我的账单","description":"","frontmatter":{"title":"财务管理 - 我的账单"},"headers":[],"relativePath":"ops-knowledge-base/billing-issues/my-bills.md","filePath":"ops-knowledge-base/billing-issues/my-bills.md","lastUpdated":1788259091000}'),n={name:"ops-knowledge-base/billing-issues/my-bills.md"};function i(a,t,e,g,d,h){return l(),o("div",null,[...t[0]||(t[0]=[s('<p>欢迎使用RakSmart客户中心。在“我的账单”页面，您可以集中查看、管理所有订单的财务记录，包括物理服务器、裸机云、VPS等产品的账单状态。以下是页面的详细功能介绍及操作指引。</p><hr><h2 id="一、-页面概览" tabindex="-1">一、 页面概览 <a class="header-anchor" href="#一、-页面概览" aria-label="Permalink to &quot;一、 页面概览&quot;">​</a></h2><p>在“客户中心”点击“财务管理” - “我的账单”后，您将进入账单管理列表页面。该页面以表格形式清晰展示了您名下所有账单的记录，并提供了强大的筛选与批量操作功能。</p><p><strong>页面顶部功能栏：</strong></p><ul><li><strong>筛选标签</strong>：支持按账单状态筛选（全部 / 已付款 / 未付款 / 已取消 / 已退款 / 已过期）。</li><li><strong>搜索框</strong>：支持输入关键词（如账单号、主机名、IP地址）进行快速查询。</li></ul><hr><h2 id="二、-账单列表字段详解" tabindex="-1">二、 账单列表字段详解 <a class="header-anchor" href="#二、-账单列表字段详解" aria-label="Permalink to &quot;二、 账单列表字段详解&quot;">​</a></h2><p>每一笔账单在列表中都会显示以下关键信息：</p><table tabindex="0"><thead><tr><th>字段名称</th><th>说明</th></tr></thead><tbody><tr><td><strong>账单#</strong></td><td>唯一的账单编号。点击可直接进入该账单的详情页。</td></tr><tr><td><strong>主机名称</strong></td><td>该账单对应订单主机名标识（如 <code>V20260208056951</code>）。</td></tr><tr><td><strong>主IP地址</strong></td><td>该产品分配的主IPv4地址。</td></tr><tr><td><strong>账单日期</strong></td><td>账单生成的日期。</td></tr><tr><td><strong>过期日期</strong></td><td>账单的支付截止日期。逾期未付可能导致服务暂停。</td></tr><tr><td><strong>总计</strong></td><td>该账单的应付金额（币种为USD美元）。</td></tr><tr><td><strong>状态</strong></td><td>当前账单的支付状态（如：未付款 / 已付款 / 已退款等）。</td></tr><tr><td><strong>操作</strong></td><td>包含对该账单的具体操作按钮。</td></tr></tbody></table><hr><h2 id="三、-核心操作说明" tabindex="-1">三、 核心操作说明 <a class="header-anchor" href="#三、-核心操作说明" aria-label="Permalink to &quot;三、 核心操作说明&quot;">​</a></h2><h3 id="_1-查看服务" tabindex="-1">1. 查看服务 <a class="header-anchor" href="#_1-查看服务" aria-label="Permalink to &quot;1. 查看服务&quot;">​</a></h3><ul><li><p><strong>位置</strong>：位于账单条目的“操作”列左侧。</p></li><li><p><strong>功能</strong>：点击 <strong>“查看服务”</strong> 按钮，系统将自动跳转至该订单对应的<strong>产品管理页面</strong>。</p></li><li><p><strong>适用场景</strong>：</p><ul><li>查看服务器的硬件配置、运行状态。</li><li>进行重启、重装系统、修改密码等运维操作。</li><li>管理该产品的附属服务。</li></ul></li></ul><h3 id="_2-查看账单" tabindex="-1">2. 查看账单 <a class="header-anchor" href="#_2-查看账单" aria-label="Permalink to &quot;2. 查看账单&quot;">​</a></h3><ul><li><p><strong>位置</strong>：位于账单条目的“操作”列右侧。</p></li><li><p><strong>功能</strong>：点击 <strong>“查看账单”</strong> 按钮，将直接进入该笔账单的<strong>详细账单页面</strong>。</p></li><li><p><strong>适用场景</strong>：</p><ul><li>核对账单明细（如续费、升级、额外IP费用等）。</li><li><strong>支付单笔账单</strong>：在该页面可直接通过支付网关完成付款。</li></ul></li></ul><h3 id="_3-批量付款" tabindex="-1">3. 批量付款 <a class="header-anchor" href="#_3-批量付款" aria-label="Permalink to &quot;3. 批量付款&quot;">​</a></h3><ul><li><p><strong>位置</strong>：位于账单列表的<strong>最底部</strong>。</p></li><li><p><strong>功能</strong>：提供合并支付功能，方便您一次性处理多笔账单。</p></li><li><p><strong>操作步骤</strong>：</p><ol><li>在账单列表中，勾选您需要支付的所有账单（通常仅支持勾选状态为“<strong>未付款</strong>”的账单）。</li><li>点击列表底部的 <strong>“批量付款”</strong> 按钮。</li><li>系统将自动跳转至结算中心，汇总您勾选的所有账单金额，生成一张合并支付单。</li><li>您只需一次支付，即可完成所有选中账单的缴费。</li></ol></li></ul><hr><h2 id="四、-状态说明" tabindex="-1">四、 状态说明 <a class="header-anchor" href="#四、-状态说明" aria-label="Permalink to &quot;四、 状态说明&quot;">​</a></h2><ul><li><strong>已付款</strong>：账单已完成支付，对应服务正常运行或已续费成功。</li><li><strong>未付款</strong>：账单待支付。请在过期日期前完成付款，以免服务中断。</li><li><strong>已退款</strong>：该笔交易已发起退款，金额将原路返回至您的支付账户。</li><li><strong>已取消</strong>：该账单已被取消（通常由于订单关闭或管理员操作）。</li><li><strong>已过期</strong>：账单已超过支付截止日期，未支付。对应的服务可能已被暂停。</li></ul><hr><p><strong>提示：</strong></p><ul><li>如果您的账单列表较长，可以使用页面右上角的 <strong>“显示”</strong> 下拉菜单，调整每页显示的记录数（如10条/页、20条/页）。</li><li>如有任何账单疑问，可点击右侧的 <strong>“在线联系客服”</strong> 获取帮助。</li></ul>',24)])])}const c=r(n,[["render",i]]);export{u as __pageData,c as default};
